"""Deterministic policy-command profiles for sim/robot A/B tests."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Iterable

import numpy as np


class ScriptedCommandProfile:
    """Generate a reproducible policy command vector over time.

    Values are in policy command space, i.e. the exact command vector that is
    concatenated into the policy observation. This intentionally bypasses the
    joystick so robot and MuJoCo runs can use the same command schedule.
    """

    BUILTIN_PROFILES = {
        "tiny": [
            (0.0, 2.0, {}, {}),
            (2.0, 3.0, {}, {"lin_vel_x": 0.08}),
            (3.0, 4.0, {"lin_vel_x": 0.08}, {"lin_vel_x": 0.08}),
            (4.0, 5.0, {"lin_vel_x": 0.08}, {}),
            (5.0, 6.0, {}, {}),
            (6.0, 7.0, {}, {"lin_vel_y": 0.08}),
            (7.0, 8.0, {"lin_vel_y": 0.08}, {"lin_vel_y": 0.08}),
            (8.0, 9.0, {"lin_vel_y": 0.08}, {}),
            (9.0, 10.0, {}, {}),
            (10.0, 11.0, {}, {"head_yaw": 0.20}),
            (11.0, 12.0, {"head_yaw": 0.20}, {"head_yaw": 0.20}),
            (12.0, 13.0, {"head_yaw": 0.20}, {"head_yaw": -0.20}),
            (13.0, 14.0, {"head_yaw": -0.20}, {"head_yaw": -0.20}),
            (14.0, 15.0, {"head_yaw": -0.20}, {}),
            (15.0, 16.0, {}, {}),
            (16.0, 17.0, {}, {"head_pitch": 0.15}),
            (17.0, 18.0, {"head_pitch": 0.15}, {"head_pitch": 0.15}),
            (18.0, 19.0, {"head_pitch": 0.15}, {}),
            (19.0, 20.0, {}, {}),
            (20.0, 21.0, {}, {"trunk_pitch_cmd": 0.10}),
            (21.0, 22.0, {"trunk_pitch_cmd": 0.10}, {"trunk_pitch_cmd": 0.10}),
            (22.0, 23.0, {"trunk_pitch_cmd": 0.10}, {}),
            (23.0, 24.0, {}, {}),
        ],
        "step": [
            (0.0, 2.0, {}, {}),
            (2.0, 3.0, {}, {"lin_vel_x": 0.10}),
            (3.0, 5.0, {"lin_vel_x": 0.10}, {"lin_vel_x": 0.10}),
            (5.0, 6.0, {"lin_vel_x": 0.10}, {}),
            (6.0, 8.0, {}, {}),
        ],
        "head": [
            (0.0, 2.0, {}, {}),
            (2.0, 3.0, {}, {"head_yaw": 0.20}),
            (3.0, 4.0, {"head_yaw": 0.20}, {"head_yaw": -0.20}),
            (4.0, 5.0, {"head_yaw": -0.20}, {}),
            (5.0, 6.0, {}, {"head_pitch": 0.15}),
            (6.0, 7.0, {"head_pitch": 0.15}, {}),
            (7.0, 8.0, {}, {}),
        ],
    }

    def __init__(self, command_names: Iterable[str], *, profile: str = "tiny", scale: float = 1.0, loop: bool = False, profile_file: str | None = None):
        self.command_names = [str(x) for x in list(command_names or [])]
        self.name_to_idx = {name: i for i, name in enumerate(self.command_names)}
        self.scale = float(scale)
        self.loop = bool(loop)
        if profile_file:
            self.segments = self._load_profile_file(profile_file)
            self.profile_name = str(profile_file)
        else:
            key = str(profile or "tiny").strip().lower()
            if key not in self.BUILTIN_PROFILES:
                valid = ", ".join(sorted(self.BUILTIN_PROFILES))
                raise ValueError(f"Unknown scripted command profile {profile!r}. Valid: {valid}")
            self.segments = list(self.BUILTIN_PROFILES[key])
            self.profile_name = key
        self.duration_s = max((float(seg[1]) for seg in self.segments), default=0.0)

    @staticmethod
    def _load_profile_file(path: str):
        p = Path(path).expanduser()
        data: Any = json.loads(p.read_text())
        raw_segments = data.get("segments", data if isinstance(data, list) else [])
        out = []
        for seg in raw_segments:
            start = float(seg["start"])
            end = float(seg["end"])
            a = dict(seg.get("from", seg.get("start_values", {})) or {})
            b = dict(seg.get("to", seg.get("end_values", {})) or {})
            out.append((start, end, a, b))
        if not out:
            raise ValueError(f"No scripted command segments found in {p}")
        return out

    def vector_at(self, t_s: float, size: int) -> np.ndarray:
        out = np.zeros(int(size), dtype=np.float32)
        if self.duration_s <= 0.0:
            return out
        t = float(t_s)
        if self.loop:
            t = t % self.duration_s
        elif t >= self.duration_s:
            return out
        if t < 0.0:
            return out
        for start, end, a, b in self.segments:
            start = float(start)
            end = float(end)
            if t < start or t > end:
                continue
            u = min(1.0, max(0.0, (t - start) / max(1e-9, end - start)))
            for name in (set(a.keys()) | set(b.keys())):
                idx = self.name_to_idx.get(str(name))
                if idx is None or idx >= len(out):
                    continue
                va = float(a.get(name, 0.0))
                vb = float(b.get(name, 0.0))
                out[idx] = (va + (vb - va) * u) * self.scale
            return out
        return out

    def write_into(self, commands, t_s: float) -> np.ndarray:
        cmd = self.vector_at(t_s, len(commands))
        commands[:] = cmd
        return cmd
